/**
 * The softphone: the one place the browser talks to Asterisk (design 4.1, 4.2).
 *
 * The phone holds no credential of its own. It asks Odoo for a session (`POST /api/v1/telephony/session`), receives a
 * short-lived extension password generated by the company's agent, and registers with it. Leaving the page, signing out
 * or the password expiring all end that registration, and the next session gets a new password.
 *
 * The library is loaded on demand, so a page that never places a call carries none of it. The state here is what the
 * header chip renders; nothing in this module touches the DOM.
 */

export type PhonePhase = 'idle' | 'connecting' | 'registered' | 'ringing' | 'calling' | 'in-call' | 'failed'

export interface PhoneSession {
  wsUrl: string
  extension: string
  password: string
  iceServers: { urls: string; username?: string; credential?: string }[]
  expiresInSeconds: number
}

export interface PhoneState {
  phase: PhonePhase
  remote: string | null
  registeredAs: string | null
  since: number | null
  failure: string | null
}

const IDLE: PhoneState = { phase: 'idle', remote: null, registeredAs: null, since: null, failure: null }

export function useSoftphone() {
  const { $api } = useApi()
  const state = reactive<PhoneState>({ ...IDLE })
  let ua: unknown = null
  let session: unknown = null

  const isBusy = computed(() => ['ringing', 'calling', 'in-call'].includes(state.phase))

  function reset(failure: string | null = null) {
    state.phase = failure ? 'failed' : 'idle'
    state.remote = null
    state.since = null
    state.failure = failure
  }

  async function loadLibrary(): Promise<any> {
    // The dependency is loaded only when a register actually happens; the bundler keeps it out of the first payload.
    const module = await import('jssip')
    return (module as any).default ?? module
  }

  async function register() {
    state.phase = 'connecting'
    state.failure = null
    try {
      const granted = await $api<PhoneSession>('/api/v1/telephony/session', { method: 'POST' })
      const JsSIP = await loadLibrary()
      const socket = new JsSIP.WebSocketInterface(granted.wsUrl)
      const agent = new JsSIP.UA({
        sockets: [socket],
        uri: `sip:${granted.extension}@${new URL(granted.wsUrl).hostname}`,
        password: granted.password,
        register: true,
        session_timers: false,
      })
      agent.on('registered', () => {
        state.phase = 'registered'
        state.registeredAs = granted.extension
      })
      agent.on('registrationFailed', (event: any) => {
        reset(`registration failed: ${event?.cause ?? 'unknown'}`)
      })
      agent.on('disconnected', () => {
        if (state.phase !== 'idle') reset('the connection closed')
      })
      agent.on('newRTCSession', (event: any) => {
        const call = event.session
        session = call
        if (event.originator === 'remote') {
          state.phase = 'ringing'
          state.remote = call.remote_identity?.uri?.user ?? null
        }
        call.on('confirmed', () => {
          state.phase = 'in-call'
          state.since = Date.now()
        })
        call.on('ended', () => reset())
        call.on('failed', (failure: any) => reset(`call failed: ${failure?.cause ?? 'unknown'}`))
      })
      agent.start()
      ua = agent
    }
    catch (error) {
      reset(error instanceof Error ? error.message : 'the phone could not start')
    }
  }

  function call(number: string) {
    const agent = ua as any
    if (!agent?.isRegistered()) return
    state.phase = 'calling'
    state.remote = number
    const target = `sip:${number}@${agent._configuration?.uri?.host ?? ''}`
    const outgoing = agent.call(target, { mediaConstraints: { audio: true, video: false } })
    session = outgoing
    outgoing.on('confirmed', () => {
      state.phase = 'in-call'
      state.since = Date.now()
    })
    outgoing.on('ended', () => reset())
    outgoing.on('failed', (failure: any) => reset(`call failed: ${failure?.cause ?? 'unknown'}`))
  }

  function answer() {
    const call = session as any
    if (!call) return
    call.answer({ mediaConstraints: { audio: true, video: false } })
  }

  function hangUp() {
    const call = session as any
    if (call) call.terminate()
    reset()
    session = null
  }

  function stop() {
    const agent = ua as any
    if (agent) agent.stop()
    ua = null
    reset()
  }

  if (import.meta.client) {
    onBeforeUnmount(stop)
  }

  return { state, isBusy, register, call, answer, hangUp, stop }
}
